private void OnKeyDown(object sender, KeyEventArgs e)
{
    if (e.Key == Key.Enter) { Submit(); e.Handled = true; }
}

protected override void OnKeyDown(KeyEventArgs e)
{
    if (e.Key == Key.Right) MoveFocus(new TraversalRequest(
        FocusNavigationDirection.Right));
}

public class AgeRule : ValidationRule
{
    public override ValidationResult Validate(object value, CultureInfo c)
        => int.TryParse(value?.ToString(), out var a) && a >= 0
            ? ValidationResult.ValidResult
            : new ValidationResult(false, "Age must be >= 0");
}
